<template>
  <main v-page-loading="{ active: pageLoading, variant: 'form', sections: 2, fields: 4 }" class="setup-page owner-theme">
    <button type="button" class="onboarding-logout" aria-label="Log out" title="Log out" @click="logout">
      <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M10 17l5-5-5-5M15 12H3m9-7h5a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2h-5" /></svg>
      <span>Log out</span>
    </button>
    <section class="setup-shell">
      <header class="setup-header">
        <span class="brand-mark" aria-hidden="true">C</span>
        <p class="eyebrow">Clinic onboarding</p>
        <h1>Set up your clinic</h1>
        <p>Set up your clinic profile and branch hours. You can update operational details later from your workspace.</p>
      </header>
      <p v-if="step > 1" class="saved-progress" role="status">Your completed steps are saved. Continue from step {{ step }}.</p>
      <ol class="steps" aria-label="Clinic setup progress">
        <li v-for="item in stepLabels" :key="item.number" :class="{ active: step === item.number, complete: step > item.number }">
          <span class="step-number">{{ step > item.number ? '✓' : item.number }}</span>
          <span class="step-copy"><b>{{ item.label }}</b><small>{{ item.hint }}</small></span>
        </li>
      </ol>
      <p v-if="error" class="error-message" role="alert"><b>There’s something to fix</b><span>{{ error }}</span></p>
      <div v-if="loading" class="setup-card loading-card" role="status"><span class="loading-dot"></span>Loading your clinic details…</div>
      <form v-else class="setup-card" @submit.prevent="nextStep">
      <section v-if="step === 1" class="form-section"><div class="section-heading"><span class="section-kicker">01 / CLINIC PROFILE</span><h2>Clinic details</h2><p>Use contact information and services customers should see for your clinic.</p></div>
        <label>Clinic name<input :value="form.clinicName || 'Clinic name unavailable'" readonly aria-readonly="true" class="locked-field" /><small class="field-hint">This is taken from your clinic registration and can’t be changed here.</small></label>
        <label>Clinic Email Address <i>*</i><input v-model.trim="form.businessEmail" required type="email" placeholder="clinic@example.com" autocomplete="email" /><small class="field-hint">The email customers can use to contact your clinic. It can be different from your personal account email.</small></label>
        <label>Clinic Phone Number <i>*</i><div class="phone-input"><b>+63</b><input v-model="form.contactNumber" required inputmode="numeric" maxlength="10" placeholder="9XXXXXXXXX" autocomplete="tel-national" @input="normalizePhone" /></div><small class="field-hint">The phone number customers can use to contact your clinic. It can be different from your personal phone number.</small></label>
        <div class="services-field"><div><span class="field-label">Services offered <i>*</i></span><small class="field-hint">Add the treatments and services your clinic provides. You can add as many as you need.</small></div><div class="service-entry"><input v-model.trim="serviceInput" type="text" maxlength="80" placeholder="e.g. Facial treatment" aria-label="Service name" @keydown.enter.prevent="addService" /><button type="button" class="add-service-button" :disabled="!serviceInput.trim()" @click="addService">Add service</button></div><div v-if="form.services.length" class="service-chips"><span v-for="service in form.services" :key="service" class="service-chip">{{ service }}<button type="button" :aria-label="`Remove ${service}`" @click="removeService(service)">×</button></span></div><p v-else class="empty-services">No services added yet.</p></div>
        <label>About your clinic <i>*</i><textarea v-model.trim="form.description" required maxlength="1000" rows="4" placeholder="Briefly describe your clinic, specialties, or services."></textarea></label>
      </section>
      <section v-else-if="step === 2" class="form-section"><div class="section-heading"><span class="section-kicker">02 / MAIN BRANCH</span><h2>Availability</h2><p>Set the usual weekly hours for your main branch. You can refine schedules later.</p></div>
        <div class="availability-panel"><div class="availability-heading"><div><span class="field-label">Weekly schedule</span><small class="field-hint">Add as many opening periods as needed for each day. For a break, use one range before it and another after.</small></div><button type="button" class="text-button" @click="applyWeekdayHours">Apply weekday hours</button></div><div class="schedule-list"><div v-for="day in days" :key="day.key" class="schedule-row" :class="{ 'is-closed': form.operatingHours[day.key].closed }"><div class="schedule-day-block"><span class="schedule-day">{{ day.label }}</span><button type="button" class="closed-toggle" :class="{ closed: form.operatingHours[day.key].closed }" :aria-pressed="form.operatingHours[day.key].closed" @click="toggleDayClosed(day.key)">{{ form.operatingHours[day.key].closed ? 'Closed' : 'Open' }}</button></div><div v-if="!form.operatingHours[day.key].closed" class="schedule-ranges"><div v-for="(range, rangeIndex) in form.operatingHours[day.key].ranges" :key="`${day.key}-${rangeIndex}`" class="schedule-range"><label class="schedule-time"><span class="sr-only">{{ day.label }} period {{ rangeIndex + 1 }} opening time</span><input v-model="range.open" type="time" /></label><span class="time-separator">to</span><label class="schedule-time"><span class="sr-only">{{ day.label }} period {{ rangeIndex + 1 }} closing time</span><input v-model="range.close" type="time" /></label><button v-if="form.operatingHours[day.key].ranges.length > 1" type="button" class="remove-range-button" :aria-label="`Remove ${day.label} period ${rangeIndex + 1}`" @click="removeScheduleRange(day.key, rangeIndex)">×</button></div><button type="button" class="add-range-button" @click="addScheduleRange(day.key)">+ Add hours</button></div><span v-else class="closed-label">No opening hours</span></div></div></div>
        <aside class="location-card"><div class="location-copy"><span class="section-kicker">VERIFIED LOCATION</span><b>Main branch location</b><span>{{ clinicLocation || 'Your verified registration address' }}</span><small>This location was confirmed during registration and is read-only.</small></div><div class="map-preview" aria-label="Read-only map preview of the verified clinic location"><iframe v-if="locationMapUrl" :src="locationMapUrl" title="Verified clinic location map" loading="lazy" referrerpolicy="no-referrer-when-downgrade" tabindex="-1"></iframe><div v-else class="map-unavailable"><span aria-hidden="true">⌖</span><b>Map preview unavailable</b><small>No verified map coordinates were saved during registration.</small></div><span v-if="locationMapUrl" class="map-lock">Read-only map</span></div></aside>
      </section>
      <section v-else-if="step === 3" class="form-section"><div class="section-heading"><span class="section-kicker">03 / PUBLIC CLINIC PROFILE</span><h2>Add your clinic images <em>Optional</em></h2><p>Upload a logo and banner for your public clinic page. You can skip either image and add it later from Clinic Setup → Clinic Profile.</p></div>
        <div class="branding-grid"><label class="branding-upload"><span>Clinic logo</span><small>Square JPG, PNG, or WebP. Up to 5 MB.</small><div class="logo-preview"> <img v-if="logoPreview" :src="logoPreview" alt="Clinic logo preview" /><span v-else>Logo preview</span></div><input type="file" accept="image/jpeg,image/png,image/webp" @change="chooseBrandingImage($event, 'logo')" /></label><label class="branding-upload"><span>Clinic banner</span><small>Wide JPG, PNG, or WebP. Up to 5 MB.</small><div class="banner-preview" :style="bannerPreview ? { backgroundImage: `url('${bannerPreview}')` } : undefined"><span v-if="!bannerPreview">Banner preview</span></div><input type="file" accept="image/jpeg,image/png,image/webp" @change="chooseBrandingImage($event, 'banner')" /></label></div>
        <p v-if="brandingError" class="error-message" role="alert">{{ brandingError }}</p><button type="button" class="text-button" @click="skipBranding">Skip images for now</button>
      </section>
      <section v-else class="form-section"><h2>Choose a plan <em>Optional</em></h2><p>You can choose a plan now, or continue with Free and upgrade any time from your dashboard.</p>
        <div v-if="plansLoading">Loading available plans…</div><div v-else class="plan-list"><button v-for="plan in plans" :key="plan.id" type="button" class="plan-card" :class="{ selected: selectedPlan === plan.id }" @click="selectedPlan = plan.id"><span>{{ plan.name }}</span><span v-if="plan.freeTrialEnabled && plan.trialDays > 0 && plan.price > 0" class="flex items-baseline gap-2"><s class="text-sm font-medium text-stone-400">{{ plan.priceLabel }}</s><strong class="text-lg text-emerald-700">PHP 0</strong></span><strong v-else>{{ plan.priceLabel }}</strong><small>{{ plan.cycleLabel }}</small><small v-if="plan.freeTrialEnabled && plan.trialDays > 0 && plan.price > 0" class="trial-plan-note">PHP 0 for {{ plan.trialDays }} days after approval, once per clinic. Later purchases use the regular price.</small><p>{{ plan.description }}</p></button></div>
      </section>
      <footer class="actions"><button v-if="step > 1" type="button" class="secondary-button" :disabled="saving" @click="step -= 1">Back</button><button v-if="step < 4" type="submit" class="primary-button" :disabled="saving">{{ saving ? 'Saving progress…' : 'Continue' }} <span aria-hidden="true">→</span></button><template v-else><button type="button" class="secondary-button" :disabled="saving" @click="finishSetup">{{ saving ? 'Saving…' : 'Skip plan for now' }}</button><button type="button" class="primary-button" :disabled="saving || !selectedPlan" @click="continueWithPlan">{{ saving ? 'Saving…' : selectedPlanIsFree ? 'Finish setup' : 'Continue to plan options' }} <span aria-hidden="true">→</span></button></template></footer>
      </form>
    </section>
  </main>
</template>

<script setup>
import { usePageLoading } from '@/composables/usePageLoading'

import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { collection, deleteField, doc, getDoc, onSnapshot, serverTimestamp, setDoc } from 'firebase/firestore'
import { getDownloadURL, ref as storageRef, uploadBytes } from 'firebase/storage'
import { auth, db, storage } from '@/config/firebaseConfig'
import { useAuth } from '@/composables/useAuth'
import { buildSubscriptionPlanCatalog, filterActiveSubscriptionPlans } from '@/utils/subscriptionPlans'
const { pageLoading, trackPageLoad, pageListener } = usePageLoading()


const router = useRouter(); const { logout } = useAuth(); const step = ref(1); const loading = ref(true); const plansLoading = ref(true); const saving = ref(false); const error = ref(''); const brandingError = ref(''); const plans = ref([]); const selectedPlan = ref(''); const clinicLocation = ref(''); const clinicLocationLat = ref(''); const clinicLocationLng = ref(''); const logoFile = ref(null); const bannerFile = ref(null); const logoPreview = ref(''); const bannerPreview = ref(''); let unsubscribePlans = null
const stepLabels = [{ number: 1, label: 'Clinic details', hint: 'Profile & services' }, { number: 2, label: 'Availability', hint: 'Branch hours' }, { number: 3, label: 'Clinic images', hint: 'Optional logo & banner' }, { number: 4, label: 'Plan', hint: 'Choose when ready' }]; const days = [{ key: 'monday', label: 'Monday' }, { key: 'tuesday', label: 'Tuesday' }, { key: 'wednesday', label: 'Wednesday' }, { key: 'thursday', label: 'Thursday' }, { key: 'friday', label: 'Friday' }, { key: 'saturday', label: 'Saturday' }, { key: 'sunday', label: 'Sunday' }]
const locationMapUrl = computed(() => { const lat = Number(clinicLocationLat.value); const lng = Number(clinicLocationLng.value); return Number.isFinite(lat) && Number.isFinite(lng) && lat >= -90 && lat <= 90 && lng >= -180 && lng <= 180 ? `https://www.google.com/maps?q=${lat},${lng}&z=15&output=embed` : '' })
const defaultOperatingHours = () => Object.fromEntries(days.map(({ key }) => [key, { ranges: [{ open: '09:00', close: '18:00' }], closed: key === 'sunday' }]))
const form = ref({ clinicName: '', businessEmail: '', contactNumber: '', description: '', services: [], operatingHours: defaultOperatingHours(), profilePicture: '', bannerPicture: '' })
const serviceInput = ref('')
const addService = () => { const service = serviceInput.value.trim(); if (!service) return; if (!form.value.services.some((entry) => entry.toLowerCase() === service.toLowerCase())) form.value.services.push(service); serviceInput.value = '' }
const removeService = (service) => { form.value.services = form.value.services.filter((entry) => entry !== service) }
const addScheduleRange = (dayKey) => { form.value.operatingHours[dayKey].ranges.push({ open: '09:00', close: '18:00' }) }
const removeScheduleRange = (dayKey, rangeIndex) => { const ranges = form.value.operatingHours[dayKey].ranges; if (ranges.length > 1) ranges.splice(rangeIndex, 1) }
const toggleDayClosed = (dayKey) => { const day = form.value.operatingHours[dayKey]; day.closed = !day.closed; if (!day.closed && !day.ranges.length) day.ranges.push({ open: '09:00', close: '18:00' }) }
const applyWeekdayHours = () => { const template = form.value.operatingHours.monday.ranges.map((range) => ({ ...range })); days.forEach(({ key }) => { const day = form.value.operatingHours[key]; day.closed = key === 'sunday'; if (key !== 'sunday') day.ranges = template.map((range) => ({ ...range })) }) }
const defaultPlans = [{ id: 'free', name: 'Free Plan', price: 0, billingCycle: 'month', description: 'One-branch service listings and online booking.', features: [], isActive: true }, { id: 'basic', name: 'Basic', price: 499, billingCycle: 'month', description: 'Core tools for daily clinic operations.', features: [], isActive: true }, { id: 'premium', name: 'Premium', price: 999, trialDays: 14, freeTrialEnabled: true, billingCycle: 'month', description: 'Advanced tools for growing clinics.', features: [], isActive: true }]
const selectedPlanData = computed(() => plans.value.find((entry) => entry.id === selectedPlan.value) || null)
const selectedPlanIsFree = computed(() => { const plan = plans.value.find((entry) => entry.id === selectedPlan.value); return String(plan?.id || '').toLowerCase() === 'free' || Number(plan?.price) === 0 })
const normalizePhone = () => { let digits = String(form.value.contactNumber || '').replace(/\D/g, ''); if (digits.startsWith('63')) digits = digits.slice(2); if (digits.startsWith('0')) digits = digits.slice(1); form.value.contactNumber = digits.slice(0, 10) }
const loadClinic = trackPageLoad(async () => { const uid = auth.currentUser?.uid; if (!uid) return router.replace('/login'); try { const snapshot = await getDoc(doc(db, 'clinics', uid)); const data = snapshot.exists() ? snapshot.data() || {} : {}; if (data.clinicSetupCompletedAt) return router.replace('/clinic/dashboard'); const draft = data.onboardingDraft || {}; if (Number(draft.completedStep) > 0) step.value = Math.min(4, Number(draft.completedStep) + 1); clinicLocation.value = String(data.clinicLocationAddress || data.clinicLocation || '').trim(); clinicLocationLat.value = String(data.clinicLocationLat || ''); clinicLocationLng.value = String(data.clinicLocationLng || ''); const operatingHours = defaultOperatingHours(); const savedHours = draft.availability || data.operatingHours; if (savedHours && typeof savedHours === 'object') { days.forEach(({ key }) => { const value = savedHours[key] || {}; const storedRanges = Array.isArray(value.ranges) ? value.ranges : (value.open || value.close ? [{ open: value.open, close: value.close }] : []); const ranges = storedRanges.map((range) => ({ open: /^\d{2}:\d{2}$/.test(String(range?.open || '')) ? range.open : '09:00', close: /^\d{2}:\d{2}$/.test(String(range?.close || '')) ? range.close : '18:00' })); operatingHours[key] = { ranges: ranges.length ? ranges : [{ open: '09:00', close: '18:00' }], closed: value.closed === true } }) } else if (Array.isArray(data.openDays)) { const dayKeys = { Mon: 'monday', Tue: 'tuesday', Wed: 'wednesday', Thu: 'thursday', Fri: 'friday', Sat: 'saturday', Sun: 'sunday' }; days.forEach(({ key }) => { const shortDay = Object.keys(dayKeys).find((short) => dayKeys[short] === key); operatingHours[key] = { ranges: [{ open: String(data.openTime || '09:00'), close: String(data.closeTime || '18:00') }], closed: !data.openDays.includes(shortDay) } }) } const details = draft.clinicDetails || {}; form.value = { ...form.value, clinicName: String(data.clinicName || data.clinicBranch || '').trim(), businessEmail: String(details.businessEmail || data.businessEmail || auth.currentUser?.email || '').trim(), contactNumber: String(details.contactNumber || data.contactNumber || '').replace(/\D/g, '').replace(/^63/, '').replace(/^0/, '').slice(0, 10), description: String(details.description || data.description || '').trim(), services: Array.isArray(details.services || data.services) ? (details.services || data.services).map((service) => String(service || '').trim()).filter(Boolean) : [], operatingHours }; form.value.profilePicture = String(draft.profilePicture || data.profilePicture || ''); form.value.bannerPicture = String(draft.bannerPicture || data.bannerPicture || ''); logoPreview.value = form.value.profilePicture; bannerPreview.value = form.value.bannerPicture } catch (reason) { console.error('Unable to load clinic setup:', reason); error.value = 'We could not load your clinic details. Please refresh and try again.' } finally { loading.value = false } })
const loadPlans = () => { unsubscribePlans = pageListener(onSnapshot, collection(db, 'subscriptionPlans'), (snapshot) => { plans.value = filterActiveSubscriptionPlans(buildSubscriptionPlanCatalog(defaultPlans, snapshot.docs)); plansLoading.value = false }, (reason) => { console.error('Unable to load plans:', reason); plans.value = defaultPlans; plansLoading.value = false }) }
const validateStep = () => { if (step.value === 1) { normalizePhone(); if (!form.value.clinicName || !form.value.businessEmail || !form.value.description || !/^9\d{9}$/.test(form.value.contactNumber)) { error.value = 'Complete the clinic contact details and enter a valid 10-digit mobile number starting with 9.'; return false } if (!form.value.services.length) { error.value = 'Add at least one service your clinic offers.'; return false } } if (step.value === 2) { const openDays = days.filter(({ key }) => !form.value.operatingHours[key].closed); if (!openDays.length || openDays.some(({ key }) => !form.value.operatingHours[key].ranges.length || form.value.operatingHours[key].ranges.some((range) => !range.open || !range.close || range.open >= range.close))) { error.value = 'Set valid opening and closing times for every period on each day the clinic is open.'; return false } } error.value = ''; return true }
const nextStep = async () => { if (!validateStep()) return; saving.value = true; try { if (step.value === 3) { if (await saveBrandingCheckpoint()) step.value = 4; return } const uid = auth.currentUser?.uid; if (!uid) return; const checkpoint = { onboardingDraft: { clinicDetails: { businessEmail: form.value.businessEmail.toLowerCase(), contactNumber: form.value.contactNumber, description: form.value.description, services: [...form.value.services] }, completedStep: step.value, updatedAt: serverTimestamp() }, updatedAt: serverTimestamp() }; if (step.value === 2) checkpoint.onboardingDraft.availability = structuredClone(form.value.operatingHours); await setDoc(doc(db, 'clinics', uid), checkpoint, { merge: true }); step.value += 1 } catch (reason) { console.error('Unable to save clinic onboarding progress:', reason); error.value = 'We could not save this step. Please try again before continuing.' } finally { saving.value = false } }
const chooseBrandingImage = (event, kind) => { const file = event.target.files?.[0]; if (!file) return; brandingError.value = ''; if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type) || file.size > 5 * 1024 * 1024) { brandingError.value = 'Choose a JPG, PNG, or WebP image up to 5 MB.'; event.target.value = ''; return } const preview = URL.createObjectURL(file); if (kind === 'logo') { if (logoPreview.value.startsWith('blob:')) URL.revokeObjectURL(logoPreview.value); logoFile.value = file; logoPreview.value = preview } else { if (bannerPreview.value.startsWith('blob:')) URL.revokeObjectURL(bannerPreview.value); bannerFile.value = file; bannerPreview.value = preview } event.target.value = '' }
const saveBrandingCheckpoint = async () => { const uid = auth.currentUser?.uid; if (!uid) return false; try { const uploadImage = async (file, kind) => { if (!file) return ''; const extension = file.name.split('.').pop()?.toLowerCase() || 'jpg'; const imageRef = storageRef(storage, `clinicMedia/${uid}/onboarding-${kind}-${Date.now()}.${extension}`); await uploadBytes(imageRef, file, { contentType: file.type }); return getDownloadURL(imageRef) }; const profilePicture = logoFile.value ? await uploadImage(logoFile.value, 'profile') : (form.value.profilePicture || ''); const bannerPicture = bannerFile.value ? await uploadImage(bannerFile.value, 'banner') : (form.value.bannerPicture || ''); await setDoc(doc(db, 'clinics', uid), { profilePicture, bannerPicture, onboardingDraft: { completedStep: 3, profilePicture, bannerPicture, updatedAt: serverTimestamp() }, updatedAt: serverTimestamp() }, { merge: true }); form.value.profilePicture = profilePicture; form.value.bannerPicture = bannerPicture; logoFile.value = null; bannerFile.value = null; return true } catch (reason) { console.error('Unable to save clinic image progress:', reason); brandingError.value = 'We could not save your images. Please retry or skip this step.'; return false } }
const skipBranding = async () => { saving.value = true; try { logoFile.value = null; bannerFile.value = null; if (logoPreview.value.startsWith('blob:')) URL.revokeObjectURL(logoPreview.value); if (bannerPreview.value.startsWith('blob:')) URL.revokeObjectURL(bannerPreview.value); logoPreview.value = form.value.profilePicture || ''; bannerPreview.value = form.value.bannerPicture || ''; if (await saveBrandingCheckpoint()) step.value = 4; brandingError.value = '' } finally { saving.value = false } }
const saveSetup = async (skippedPlan = false) => { if (!validateStep()) return false; const uid = auth.currentUser?.uid; if (!uid) return false; saving.value = true; try { if (logoFile.value || bannerFile.value) { if (!await saveBrandingCheckpoint()) return false } const publishedAt = serverTimestamp(); await setDoc(doc(db, 'clinics', uid), { profilePicture: form.value.profilePicture || '', bannerPicture: form.value.bannerPicture || '', businessEmail: form.value.businessEmail.toLowerCase(), contactNumber: form.value.contactNumber, description: form.value.description, services: form.value.services, operatingHours: form.value.operatingHours, isPublished: true, publishedAt, clinicSetupRequired: false, clinicSetupCompletedAt: publishedAt, clinicSetupVersion: 1, onboardingDraft: deleteField(), ...(skippedPlan ? { clinicSetupPlanSkippedAt: serverTimestamp() } : {}), updatedAt: serverTimestamp() }, { merge: true }); return true } catch (reason) { console.error('Unable to complete clinic setup:', reason); error.value = 'We could not save your clinic setup. Please try again.'; return false } finally { saving.value = false } }
const finishSetup = async () => { if (await saveSetup(true)) await router.replace('/clinic/dashboard') }
const continueWithPlan = async () => { if (!selectedPlan.value) return; if (selectedPlanIsFree.value) { if (await saveSetup()) await router.replace('/clinic/dashboard'); return } if (await saveSetup()) await router.push({ path: '/account/plans', query: { plan: selectedPlan.value } }) }
onMounted(trackPageLoad(() => { loadClinic(); loadPlans() })); onBeforeUnmount(() => { unsubscribePlans?.(); if (logoPreview.value.startsWith('blob:')) URL.revokeObjectURL(logoPreview.value); if (bannerPreview.value.startsWith('blob:')) URL.revokeObjectURL(bannerPreview.value) })
</script>

